                if grid[r][c]==bg: out[r][c]=2
    for c in range(w):
        ys=[r for r in range(h) if grid[r][c]==mark]
        for a,b in zip(ys,ys[1:]):
            for r in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    return out
